    "devDependencies": {
        "@biomejs/biome": "^2.5.1",
        "@types/better-sqlite3": "^7.6.13",
        "@types/node": "^22.20.0",
        "typescript": "^5.8.0"
    },
    "engines": {
        "node": "^22.16.0 || >=24.0.0"
    }
}

